/*
# Seed Batch C: 3 draft surveys from surveys_spec.json

Inserts 3 surveys as drafts (status='draft') into guidance_surveys, linked to
indicators/programs/resources from the Zad reference tables. Idempotent via
ON CONFLICT (slug) DO NOTHING.

Surveys:
1. beneficiary_satisfaction — قياس رضا المستفيد (12 items, 4 sections + NPS + matrix_importance)
2. career_interests — مقياس الميول المهنية (24 items, 6 sections)
3. graduate_celebration — رضا الفئات عن برنامج الاحتفاء بالخريجين (12 items, 5 sections)

No schema changes. No RLS changes. Data-only migration.
*/

INSERT INTO guidance_surveys (slug, title, audience, status, scale, intro, demographics, sections, extra, settings, indicators, programs, resources, publish_gate) VALUES ('beneficiary_satisfaction', 'قياس رضا المستفيد عن خدمات التوجيه الطلابي', 'student|parent|teacher', 'draft', '{"type":"likert5","labels":["غير راضٍ إطلاقًا","غير راضٍ","محايد","راضٍ","راضٍ جدًا"]}'::jsonb, 'رأيك يساعدنا في تطوير خدمات التوجيه الطلابي. الاستبيان مجهول.', '[{"id":"role","text":"صفتك","type":"single","options":["طالب","ولي أمر","معلم"]}]'::jsonb, '[{"id":"access","name":"سهولة الوصول والتواصل","swot_axis":"internal","items":[{"text":"سهولة الوصول إلى الموجه الطلابي عند الحاجة.","reverse":false},{"text":"وضوح مواعيد وأماكن تقديم الخدمة.","reverse":false},{"text":"سرعة الاستجابة لطلبي أو ملاحظتي.","reverse":false}],"if_low":["تحديد ساعات مكتبية معلنة وقناة تواصل رسمية"]},{"id":"quality","name":"جودة الخدمة والمهنية","swot_axis":"internal","items":[{"text":"وضوح الإجراءات المتبعة في معالجة الحالة أو الموقف.","reverse":false},{"text":"تنوع البرامج والأنشطة الإرشادية المقدمة.","reverse":false},{"text":"كفاية المعلومات التي أحصل عليها من الموجه.","reverse":false}],"if_low":["مراجعة البرامج المقدمة وتنويع الأنشطة"]},{"id":"respect","name":"الاحترام والسرية","swot_axis":"internal","items":[{"text":"احترام الموجه لخصوصيتي وسرية ما أذكره.","reverse":false},{"text":"أسلوب التعامل واللباقة.","reverse":false},{"text":"الشعور بالأمان عند طرح مشكلتي.","reverse":false}],"if_low":["تذكير بميثاق السرية وحدودها في بداية كل لقاء"]},{"id":"impact","name":"الأثر والفائدة","swot_axis":"internal","items":[{"text":"مدى مساعدة خدمات التوجيه على تحسين وضعي (أو وضع ابني).","reverse":false},{"text":"تحسن السلوك أو التحصيل أو التكيف بعد الاستفادة من الخدمة.","reverse":false},{"text":"الاستعداد لتوصية الآخرين بخدمات التوجيه.","reverse":false}],"if_low":["متابعة بعدية للحالات وقياس أثر التدخلات"]}]'::jsonb, '[{"id":"importance","text":"قيّم أهمية كل بُعد لك (1–5) للاستخدام في مصفوفة الأهمية والأداء","type":"matrix_importance","dims":["access","quality","respect","impact"]},{"id":"nps","text":"ما احتمال أن تنصح غيرك بخدمات التوجيه الطلابي؟ (0–10)","type":"nps"},{"id":"open1","text":"ما أكثر ما أعجبك؟","type":"text"},{"id":"open2","text":"ما الذي تقترح تحسينه؟","type":"text"}]'::jsonb, '{"anonymous":true,"one_response_per_device":true}'::jsonb, ARRAY['1-2-1-1','1-2-1-3','1-3-1-1','1-3-1-2','1-5-1-1','3-2-1-5']::text[], ARRAY['family']::text[], ARRAY['org_plan','g_family']::text[], NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO guidance_surveys (slug, title, audience, status, scale, intro, demographics, sections, extra, settings, indicators, programs, resources, publish_gate) VALUES ('career_interests', 'مقياس الميول المهنية', 'student', 'draft', '{"type":"likert5","labels":["لا أميل إطلاقًا","أميل قليلًا","محايد","أميل","أميل جدًا"]}'::jsonb, 'اختر مدى ميلك لكل نشاط كما لو كنت تستطيع ممارسته. لا علاقة لذلك بدرجاتك. النتيجة تساعدك في التفكير بالمجالات الأقرب لك.', '[{"id":"grade","text":"الصف","type":"single","options":["الأول الثانوي","الثاني الثانوي","الثالث الثانوي"]}]'::jsonb, '[{"id":"R","name":"عملي/ميداني (الأدوات والآلات والعمل الميداني)","swot_axis":"external","items":[{"text":"إصلاح جهاز أو تركيب قطعة ميكانيكية.","reverse":false},{"text":"العمل في الورش أو المعامل أو الهواء الطلق.","reverse":false},{"text":"تشغيل أدوات ومعدات متخصصة.","reverse":false},{"text":"بناء نماذج أو مشاريع بيدي.","reverse":false}],"if_low":[]},{"id":"I","name":"بحثي/تحليلي","swot_axis":"external","items":[{"text":"إجراء تجربة علمية وتحليل نتائجها.","reverse":false},{"text":"حل ألغاز ومسائل معقدة.","reverse":false},{"text":"قراءة أبحاث أو متابعة اكتشافات علمية.","reverse":false},{"text":"تحليل بيانات للوصول إلى استنتاجات.","reverse":false}],"if_low":[]},{"id":"A","name":"فني/إبداعي","swot_axis":"external","items":[{"text":"كتابة قصة أو تصميم شعار أو رسم.","reverse":false},{"text":"تصوير ومونتاج مقاطع أو تصميم محتوى.","reverse":false},{"text":"ابتكار أفكار جديدة غير تقليدية.","reverse":false},{"text":"المشاركة في أنشطة مسرحية أو إنشادية.","reverse":false}],"if_low":[]},{"id":"S","name":"اجتماعي/خدمي","swot_axis":"external","items":[{"text":"مساعدة زملائي على فهم دروسهم.","reverse":false},{"text":"المشاركة في أعمال تطوعية.","reverse":false},{"text":"الاستماع لمشكلات الآخرين ودعمهم.","reverse":false},{"text":"تنظيم فعاليات تخدم المجتمع.","reverse":false}],"if_low":[]},{"id":"E","name":"ريادي/قيادي","swot_axis":"external","items":[{"text":"قيادة فريق لتنفيذ فكرة.","reverse":false},{"text":"إقناع الآخرين بفكرة أو منتج.","reverse":false},{"text":"إطلاق مشروع تجاري صغير.","reverse":false},{"text":"اتخاذ قرارات وتحمّل مسؤوليتها.","reverse":false}],"if_low":[]},{"id":"C","name":"تنظيمي/إداري","swot_axis":"external","items":[{"text":"ترتيب الملفات والجداول وتنظيم البيانات.","reverse":false},{"text":"اتباع خطة دقيقة خطوة بخطوة.","reverse":false},{"text":"العمل بالأرقام والحسابات والسجلات.","reverse":false},{"text":"مراجعة الأعمال للتأكد من خلوها من الأخطاء.","reverse":false}],"if_low":[]}]'::jsonb, '[]'::jsonb, '{"anonymous":true,"one_response_per_device":true}'::jsonb, ARRAY['1-3-1-2','2-1-1-9']::text[], ARRAY['career']::text[], ARRAY['p_career']::text[], NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO guidance_surveys (slug, title, audience, status, scale, intro, demographics, sections, extra, settings, indicators, programs, resources, publish_gate) VALUES ('graduate_celebration', 'رضا الفئات عن برنامج الاحتفاء بالخريجين', 'student|parent|graduate', 'draft', '{"type":"likert5","labels":["غير راضٍ إطلاقًا","غير راضٍ","محايد","راضٍ","راضٍ جدًا"]}'::jsonb, 'شاركنا رأيك في حفل وبرنامج الاحتفاء بالخريجين لنطوّره.', '[{"id":"role","text":"صفتك","type":"single","options":["خريج","طالب","ولي أمر","معلم"]}]'::jsonb, '[{"id":"organization","name":"التنظيم والإدارة","swot_axis":"internal","items":[{"text":"وضوح البرنامج الزمني والإعلان المسبق للحفل.","reverse":false},{"text":"حسن الاستقبال وتنظيم الجلوس والحضور.","reverse":false}],"if_low":["إعداد دليل تنظيمي وقائمة مراجعة للحفل"]},{"id":"content","name":"المحتوى والفقرات","swot_axis":"internal","items":[{"text":"تنوع الفقرات وجودة الكلمات والفعاليات.","reverse":false},{"text":"مشاركة الطلاب في تقديم الفقرات.","reverse":false}],"if_low":["إشراك الطلاب في تصميم الفقرات"]},{"id":"recognition","name":"التقدير والتكريم","swot_axis":"internal","items":[{"text":"عدالة اختيار المكرَّمين ووضوح معاييرهم.","reverse":false},{"text":"أثر التكريم في إشعار الخريج بالتقدير.","reverse":false}],"if_low":["مراجعة معايير التكريم وفق إطار الاحتفاء والتكريم"]},{"id":"belonging","name":"الانتماء والذكرى","swot_axis":"external","items":[{"text":"عزّز الحفل شعوري (أو شعور ابني) بالانتماء للمدرسة.","reverse":false},{"text":"وفّر الحفل ذكرى جميلة ووثّق الإنجازات.","reverse":false}],"if_low":["توثيق الحفل (ألبوم/فيديو) وإرسال تقارير للأسر"]},{"id":"overall","name":"الرضا العام","swot_axis":"internal","items":[{"text":"رضاي العام عن الحفل.","reverse":false},{"text":"سأنصح بالمشاركة في حفلات المدرسة القادمة.","reverse":false}],"if_low":[]}]'::jsonb, '[{"id":"open1","text":"أجمل لحظة في الحفل:","type":"text"},{"id":"open2","text":"ما الذي تقترح تطويره للحفل القادم؟","type":"text"}]'::jsonb, '{"anonymous":true,"one_response_per_device":true}'::jsonb, ARRAY['1-2-1-4','1-3-1-2']::text[], ARRAY['honor']::text[], ARRAY['g_honor']::text[], NULL) ON CONFLICT (slug) DO NOTHING;